let fulfilmentTab='queue',fulfilmentState;
async function fulfilmentView(){
 $('#view').innerHTML=page('Staff order queue.','Accept, pack, assign and fulfil orders with a clear status history.')+'<div class="panel" id="fulfilment-loading">Loading fulfilment…</div>';
 try{fulfilmentState=await api('/fulfilment');store=await api('/store');if(view!=='fulfilment')return;
 $('#view').innerHTML=page('Staff order queue.','The signed-in store owner manages this queue. Separate staff accounts are not enabled.','<button class="btn secondary" id="refresh-fulfilment">Refresh</button>')+`<div class="mode-tabs">${[['queue','Orders & packing'],['notifications','Notification logs'],['settings','Team & notifications']].map(([id,label])=>`<button data-fulfilment-tab="${id}" class="${fulfilmentTab===id?'active':''}">${label}</button>`).join('')}</div><div id="fulfilment-content"></div>`;
 $('#refresh-fulfilment').onclick=fulfilmentView;$$('[data-fulfilment-tab]').forEach(b=>b.onclick=()=>{fulfilmentTab=b.dataset.fulfilmentTab;fulfilmentContent()});fulfilmentContent();
 }catch(e){if($('#fulfilment-loading'))$('#fulfilment-loading').textContent=e.message;else toast(e.message)}
}
function fulfilmentContent(){
 const state=fulfilmentState,cfg=state.config;
 if(fulfilmentTab==='queue'){$('#fulfilment-content').innerHTML=`<div class="stats">${['New','Accepted','Packed','Out for delivery'].map(status=>`<div class="stat"><div class="stat-label">${status}</div><div class="value">${state.orders.filter(o=>o.status===status).length}</div></div>`).join('')}</div><div class="panel"><div class="toolbar"><select id="staff-order-filter"><option>Active orders</option><option>All orders</option>${['New','Accepted','Packed','Out for delivery','Delivered','Cancelled'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="staff-order-table"></div></div>`;$('#staff-order-filter').onchange=fulfilmentRows;fulfilmentRows()}
 if(fulfilmentTab==='notifications'){$('#fulfilment-content').innerHTML=`<div class="note">Accepted means the provider accepted the message; it does not prove delivered/read. Unknown sends are never retried automatically. Disabled recipients, cancelled staff tasks and superseded customer status updates are skipped.</div><div class="panel">${table(['TIME','RECIPIENT','ORDER','RESULT','ATTEMPTS','DETAIL',''],state.notifications.map(n=>row([date(n.created_at),esc(n.recipient_type)+'<small>'+esc(n.phone)+'</small>',esc(state.orders.find(o=>o.id===n.order_id)?.number||n.order_id),pill(n.status),n.attempts,esc(n.error||n.provider_id||'Queued'),['Failed','Blocked'].includes(n.status)?`<button class="btn small secondary" data-notification-retry="${n.id}">Retry</button>`:'—'])))}</div>`;$$('[data-notification-retry]').forEach(b=>b.onclick=async()=>{if(!confirm('Retry this definitely failed/blocked notification using the current saved permissions?'))return;try{await api('/fulfilment/notifications/'+b.dataset.notificationRetry+'/retry','POST',{});fulfilmentView();toast('Notification queued for retry')}catch(e){toast(e.message)}})}
 if(fulfilmentTab==='settings'){$('#fulfilment-content').innerHTML=`<div class="panel setting-panel"><h3>Team and notification settings</h3><form id="fulfilment-config"><label class="check"><input name="enabled" type="checkbox" ${cfg.enabled?'checked':''}>Enable fulfilment notifications</label><label class="check"><input name="staffNewOrders" type="checkbox" ${cfg.staffNewOrders?'checked':''}>Notify permitted staff about new orders and assignments</label><label class="check"><input name="customerUpdates" type="checkbox" ${cfg.customerUpdates?'checked':''}>Notify customers about accepted, packed, dispatched and completed orders</label><label class="check"><input name="paymentLinksEnabled" type="checkbox" ${cfg.paymentLinksEnabled?'checked':''}>Allow requested payment-link messages</label><label class="check"><input name="receiptsEnabled" type="checkbox" ${cfg.receiptsEnabled?'checked':''}>Send receipts after verified live payment</label>${input('paymentLinkTemplateName','Payment link UTILITY template',cfg.paymentLinkTemplateName||'')}${input('receiptTemplateName','Receipt UTILITY template',cfg.receiptTemplateName||'')}${select('mode','Connection',['official','web'],cfg.mode||'official')}<label>Staff contacts (one per line: Name | international phone | YES or NO)<textarea name="staffContacts" rows="5" placeholder="Packing Staff | 919876543210 | YES">${esc((cfg.staffContacts||[]).map(s=>`${s.name} | ${s.phone} | ${s.serviceConsent?'YES':'NO'}`).join('\n'))}</textarea></label><p class="hint">YES records actual permission to send operational WhatsApp alerts, including customer/order details. NO allows assignment without WhatsApp alerts. Enter only verified staff numbers.</p><div class="two-fields">${input('staffTemplateName','Official staff UTILITY template',cfg.staffTemplateName||'')}${input('customerTemplateName','Official customer UTILITY template',cfg.customerTemplateName||'')}</div>${input('language','Exact template language',cfg.language||'en')}<div class="note">Official free-text messages require a customer/staff reply in the previous 24 hours. Otherwise configure approved UTILITY templates with 3 body parameters: order number; customer name (staff template) or status (customer template); notification details. No dynamic headers or buttons are supported.</div><div class="note warning">Enabling notifications affects future order changes. It does not replay past events. Live sending needs the selected WhatsApp connection. Notifications do not change payment status.</div><button class="btn">Save team settings</button></form></div>`;$('#fulfilment-config').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));const contacts=b.staffContacts.split('\n').filter(s=>s.trim()).map(line=>{const parts=line.split('|').map(s=>s.trim());if(parts.length!==3||!['YES','NO'].includes(parts[2].toUpperCase()))throw Error('Each staff row needs Name | phone | YES or NO');return{name:parts[0],phone:parts[1],serviceConsent:parts[2].toUpperCase()==='YES'}});await api('/fulfilment/config','POST',{...b,enabled:b.enabled==='on',staffNewOrders:b.staffNewOrders==='on',customerUpdates:b.customerUpdates==='on',paymentLinksEnabled:b.paymentLinksEnabled==='on',receiptsEnabled:b.receiptsEnabled==='on',staffContacts:contacts});toast('Team and notification settings saved');fulfilmentView()}catch(e){toast(e.message)}}}
}
function fulfilmentRows(){const filter=$('#staff-order-filter').value;const orders=fulfilmentState.orders.filter(o=>filter==='All orders'||filter==='Active orders'&&!['Delivered','Cancelled'].includes(o.status)||o.status===filter).slice().reverse();$('#staff-order-table').innerHTML=table(['ORDER','CUSTOMER','FULFILMENT','ASSIGNED','STATUS',''],orders.map(o=>{const c=o.customerSnapshot||customer(o.customerId)||{};return row([`<b>${esc(o.number)}</b><small>${date(o.at)}</small>`,esc(c.name||'Customer')+'<small>'+esc(c.phone)+'</small>',esc(o.fulfilment)+'<small>'+esc(o.slot||'Slot not set')+'</small>',esc(o.assignee||'Unassigned'),pill(o.status),`<button class="btn small secondary" data-pack-order="${o.id}">Manage</button>`])}));$$('[data-pack-order]').forEach(b=>b.onclick=()=>manageFulfilment(b.dataset.packOrder))}
function manageFulfilment(oid){const o=fulfilmentState.orders.find(o=>o.id===oid),c=o.customerSnapshot||customer(o.customerId)||{},cfg=fulfilmentState.config;const transitions={New:['Accepted','Cancelled'],Accepted:['Packed','Cancelled'],Packed:o.fulfilment==='Store pickup'?['Delivered','Cancelled']:['Out for delivery','Cancelled'],'Out for delivery':['Delivered','Cancelled'],Delivered:[],Cancelled:[]};
 modal(`<h2>${esc(o.number)} · ${esc(o.status)}</h2><div class="note"><b>${esc(c.name)}</b><br>${esc(c.phone)}<br>${o.fulfilment==='Store pickup'?'Store pickup':esc(c.address||'Address needs confirmation')+' '+esc(c.postcode||'')}<br>Payment record: ${esc(o.payment||'Unpaid')} (unchanged by fulfilment)</div><form id="edit-form"><h3>Item packing checklist</h3>${o.items.map(i=>`<label class="check"><input type="checkbox" name="packed" value="${esc(i.productId)}" ${o.packingChecks?.includes(i.productId)?'checked':''}>${esc(i.qty)} x ${esc(i.name)} (${esc(i.unit)})</label>`).join('')}<label>Assign staff<select name="assigneeId"><option value="">Unassigned</option>${(cfg.staffContacts||[]).map(s=>`<option value="${esc(s.id)}" ${s.id===o.assigneeId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${input('slot','Slot / delivery instructions',o.slot||'','text','maxlength="250"')}${select('status','Next status',[o.status,...(transitions[o.status]||[])],o.status)}<p class="hint">Check every item before marking Packed. Delivered means collected for pickup orders. Cancellation restores reserved stock; it does not refund payment.</p><button type="button" class="btn secondary small" id="view-order-history">View status history</button>${formEnd('Save fulfilment')}`);
 $('#view-order-history').onclick=async()=>{try{const history=await api('/fulfilment/orders/'+oid+'/history');modal(`<h2>Status history · ${esc(o.number)}</h2>${table(['TIME','CHANGE','FROM','TO','ASSIGNED'],history.map(h=>row([date(h.created_at),esc(h.kind),esc(h.previous_status||'—'),esc(h.status),esc(h.assignee||'—')])))}`)}catch(e){toast(e.message)}};
 bindForm(async(b,form)=>{if(b.status==='Cancelled'&&o.status!=='Cancelled'&&!confirm('Cancel this order and restore reserved stock? Any payment/refund still needs separate handling.'))throw Error('Cancellation not applied');await api('/fulfilment/orders/'+oid,'PATCH',{status:b.status,expectedStatus:o.status,assigneeId:b.assigneeId,slot:b.slot,packingChecks:new FormData(form).getAll('packed')});await fulfilmentView();toast('Fulfilment saved. Check notification logs for sending results.')});
}
const automationBeforeStep6=automations;
automations=async function(){await automationBeforeStep6();if(view==='automations'){$('.card-row',$('#view')).filter(r=>['Welcome replies','Automatic order confirmations','Automatic delivery updates'].includes($('b',r)?.textContent)).forEach(r=>r.remove());$('.panel',$('#view')).insertAdjacentHTML('afterbegin','<div class="card-row"><span class="row-icon">▤</span><div><b>Staff queue and customer status updates</b><small>Order acceptance, packing, assignment and notification logs</small></div><button class="btn" id="configure-fulfilment">Configure</button></div>');$('#configure-fulfilment').onclick=()=>navigate('fulfilment')}};
